	}
	if !strings.Contains(output, "ID") || !strings.Contains(output, "BRANCH") {
		t.Error("static output missing column headers")
	}
	if !strings.Contains(output, "a3b2c4d5e6") {
		t.Error("static output missing first result ID")
	}
	if !strings.Contains(output, "d5e6f789ab") {
		t.Error("static output missing second result ID")
	}
}

func TestComputeColumns(t *testing.T) {
	t.Parallel()

	cols := computeColumns(80)
	total := cols.id + cols.branch + cols.prompt + cols.author + cols.age + 8 // 8 for gaps
	if total > 80 {
		t.Errorf("columns exceed terminal width: %d > 80", total)
	}
	if cols.id != 10 {
		t.Errorf("id width = %d, want 10", cols.id)
	}
	if cols.author != 12 {
		t.Errorf("author width = %d, want 12", cols.author)
	}

	// Narrow terminal
	cols = computeColumns(40)
	if cols.branch < 8 {
		t.Errorf("branch width on narrow terminal = %d, want >= 8", cols.branch)
	}
}

